"""Seal V01 prospective contract data; no native lifecycle/installation calls."""
from pathlib import Path
import hashlib
import sys
from adapter.planner import codec as c

R=Path(__file__).resolve().parents[2]
D=R/'docs/plans'
O=D/'qualification/VALIDATION_V01_1'
Q=D/'qualification/E2_P04_CONTINUATION_INPUT_CLOSURE_1'
NAME='DETERMINISTIC_PLANNER_V0_1_VALIDATION_V01_A10_CONTRACT'
REFRESH='--refresh-unselected-draft' in sys.argv
def read(p): return c.parse_json(p.read_bytes())
def ident(obj,namespace='raw-file-sha256',raw=False):
    return {'kind':'CONTENT_IDENTITY','namespace':namespace,'sha256':hashlib.sha256(obj if raw else c.canonical_bytes(obj)).hexdigest()}
def pin(p):
    return {'path':str(p.relative_to(R)),'profile':'raw-file-sha256','pointer':'','identity':ident(p.read_bytes(),raw=True)}
def emit(name,obj):
    p=O/name;raw=c.canonical_bytes(obj)
    if p.exists() and p.read_bytes()!=raw:
        old=read(D/(NAME+'.json'))
        assert REFRESH and old['SELECTED_OPTION']=='NONE' and old['AUTHORITY_ISSUED']=='NO' and old['DEFINITIONS_INSTALLED']=='NO','sealed contract changed: '+name
        p.write_bytes(raw)
    elif not p.exists():p.write_bytes(raw)
    return pin(p)
def member(name,typ,schema,body,subject,ctx):
    p=emit(name,{'schema':schema,'contract':body})
    descriptor={'schema':'PLANNER-INSTALLABLE-DEFINITION-1','definition_type':typ,'canonical_body_schema':schema,
       'content_id':p['identity'],'subject':subject,**ctx,
       'canonical_source_reference':{'kind':'IMMUTABLE_FILE','path':p['path'],'content_id':p['identity']},
       'source_pin':p,'provenance':{'path':p['path'],'content_id':p['identity'],'section':'/','method':'VALIDATION-V01-PROSPECTIVE-CONTRACT','scope':ctx['scope']},
       'currentness_rule':{'schema':'PLANNER-DEFINITION-CURRENTNESS-1','rule_id':'VALIDATION_SUPPORT_SET_CURRENT_V1',
         'consumer':subject['consumer'],'installation_required':True,'authority_current_required':True,
         'source_current_required':True,'exact_scope_lineage_generation_required':True,
         'activation_witness':'MEMBER_OF_ONE_ATOMIC_INSTALLED_SET; NOT_INDIVIDUALLY_INSTALLABLE'}}
    return {'definition_id':ident(descriptor,'planner-installable-definition-v1'),'descriptor':descriptor,'body':body,'body_pin':p}

def run():
    O.mkdir(parents=True,exist_ok=True)
    bundle_path=D/'DETERMINISTIC_PLANNER_V0_1_E2_P04_POST_ATTEST_INSTALL_BUNDLE_1.json'
    b=read(bundle_path)['bundle'];s=b['current'];ctx={k:s['context'][k] for k in ('scope','lineage','generation')}
    requirement=s['evidence_requirements'][0];gate=s['external_gates'][0]
    payload=read(Q/'semantic-payload.json');binding=read(Q/'evidence-binding.json')['binding']['fields']
    native_binding={k:c._wire(c._unwire(v)) for k,v in binding.items()}
    binding_template_pin=emit('p04-semantic-native-binding-template.json',{
        'schema':'PLANNER-SEMANTIC-NATIVE-BINDING-TEMPLATE-1','template_only':True,'binding':native_binding,
        'instance_boundary':'No GraphEntity, receipt, EvidenceBoundAttestation, operand or lifecycle result in this definition source; actual A09 evidence resolves at execution'})
    # Earlier dossier validation remains canonical history, not A10 evidence validation.
    assert not s.get('validation_results') and not s.get('typed_proofs')
    assert not any(e['kind']['value']=='EVIDENCE' for e in s['entities'])
    union_source=(R/'adapter/planner/model.py').read_text()
    assert "'ValidationSupportAdmission'" not in union_source
